async function main(ctx) {
  const input = ctx.input || {};

  const conversationIdRaw = input.conversationId ?? ctx.env('CONVERSATION_ID') ?? undefined;
  const conversationId = conversationIdRaw === undefined ? '' : String(conversationIdRaw).trim();
  if (!conversationId) throw new Error('conversationId is required (or provide runtime CONVERSATION_ID)');

  const limitRaw = input.limit;
  const limit = limitRaw === undefined || limitRaw === null || limitRaw === '' ? 10 : Number(limitRaw);
  if (!Number.isFinite(limit) || limit <= 0 || limit > 200) throw new Error('limit must be a number between 1 and 200');

  const offsetRaw = input.offset;
  const offset = offsetRaw === undefined || offsetRaw === null || offsetRaw === '' ? 0 : Number(offsetRaw);
  if (!Number.isFinite(offset) || offset < 0) throw new Error('offset must be a number >= 0');

  const orderDirectionRaw = (input.orderDirection ?? 'desc').toString().trim().toLowerCase();
  const orderDirection = orderDirectionRaw === 'asc' ? 'asc' : 'desc';

  const beforeId = input.beforeId ?? undefined;
  const beforeCreatedAt = input.beforeCreatedAt ?? undefined;
  const hasBeforeId = typeof beforeId === 'string' && beforeId.trim().length > 0;
  const hasBeforeCreatedAt = typeof beforeCreatedAt === 'string' && beforeCreatedAt.trim().length > 0;
  if (hasBeforeId !== hasBeforeCreatedAt) {
    throw new Error('beforeId and beforeCreatedAt must be provided together');
  }

  const args = {
    conversationId,
    limit,
    offset,
    orderDirection,
    beforeId: hasBeforeId ? String(beforeId) : undefined,
    beforeCreatedAt: hasBeforeCreatedAt ? String(beforeCreatedAt) : undefined,
  };

  for (const k of Object.keys(args)) {
    if (args[k] === undefined) delete args[k];
  }

  return args;
}

async function main(ctx) {
  const resp = ctx.input || {};
  const body = resp && typeof resp === 'object' ? resp.body : undefined;
  if (body && typeof body === 'object' && body.success === true && 'data' in body) return body.data;
  return body ?? resp;
}
